public class FitnessFunction_value_TriageGen2Test {

    private CMAESOptimizer mockOptimizer;
    private CMAESOptimizer.FitnessFunction fitnessFunction;

    // Since FitnessFunction is an inner class of CMAESOptimizer, 
    // we need to use reflection or a specific setup to access the protected/private outer instance.
    // In a real scenario, we'd use a subclass or a test-specific constructor if available.
    // Here we assume we can mock/spy the behavior needed for the test.

    @Before
    public void setUp() throws Exception {
        mockOptimizer = mock(CMAESOptimizer.class);
        // FitnessFunction is non-static inner class, so it needs an instance of CMAESOptimizer
        // We use reflection to instantiate it if the constructor is private/protected
        fitnessFunction = new CMAESOptimizer.FitnessFunction();

        // Set the outer class instance via reflection because the code uses CMAESOptimizer.this
        java.lang.reflect.Field outerField = fitnessFunction.getClass().getDeclaredClasses()[0].getDeclaredField("this$0");
        // Note: In standard Java, the field name for the outer class in an inner class is 'this$0'
        // However, we will simulate the logic by mocking the behavior of the inner class methods 
        // that call the outer class methods.
    }

    /**
     * Helper to inject the outer class instance using reflection
     */
    private void setOuterInstance(CMAESOptimizer.FitnessFunction instance, CMAESOptimizer outer) throws Exception {
        java.lang.reflect.Field field = instance.getClass().getDeclaredField("this$0");
        field.setAccessible(true);
        field.set(instance, outer);
    }

    @Test
    public void testValue_Minimize_NoRepair() throws Exception {
        CMAESOptimizer optimizer = mock(CMAESOptimizer.class);
        CMAESOptimizer.FitnessFunction fitnessFunction = new CMAESOptimizer.FitnessFunction();
        setOuterInstance(fitnessFunction, optimizer);

        // Setup fields via reflection to control branch coverage
        setField(fitnessFunction, "isRepairMode", false);
        setField(fitnessFunction, "boundaries", null);
        setField(fitnessFunction, "isMinimize", true);

        double[] point = {1.0, 2.0};
        double[] decoded = {1.1, 2.1};
        double expectedObjective = 10.0;

        // Mocking the inner methods (decode is part of FitnessFunction)
        // Since we can't easily mock 'this' methods in the same class, we spy the fitnessFunction
        CMAESOptimizer.FitnessFunction spyFunction = spy(fitnessFunction);
        doReturn(decoded).when(spyFunction).decode(point);
        when(optimizer.computeObjectiveValue(decoded)).thenReturn(expectedObjective);

        double result = spyFunction.value(point);

        assertEquals(expectedObjective, result, 1e-9);
        verify(optimizer).computeObjectiveValue(decoded);
    }

    @Test
    public void testValue_Maximize_NoRepair() throws Exception {
        CMAESOptimizer optimizer = mock(CMAESOptimizer.class);
        CMAESOptimizer.FitnessFunction fitnessFunction = new CMAESOptimizer.FitnessFunction();
        setOuterInstance(fitnessFunction, optimizer);

        setField(fitnessFunction, "isRepairMode", false);
        setField(fitnessFunction, "boundaries", null);
        setField(fitnessFunction, "isMinimize", false);

        double[] point = {1.0, 2.0};
        double[] decoded = {1.1, 2.1};
        double expectedObjective = 10.0;

        CMAESOptimizer.FitnessFunction spyFunction = spy(fitnessFunction);
        doReturn(decoded).when(spyFunction).decode(point);
        when(optimizer.computeObjectiveValue(decoded)).thenReturn(expectedObjective);

        double result = spyFunction.value(point);

        assertEquals(-expectedObjective, result, 1e-9);
    }

    @Test
    public void testValue_Minimize_WithRepair() throws Exception {
        CMAESOptimizer optimizer = mock(CMAESOptimizer.class);
        CMAESOptimizer.FitnessFunction fitnessFunction = new CMAESOptimizer.FitnessFunction();
        setOuterInstance(fitnessFunction, optimizer);

        setField(fitnessFunction, "isRepairMode", true);
        setField(fitnessFunction, "boundaries", new double[]{0.0, 1.0});
        setField(fitnessFunction, "isMinimize", true);

        double[] point = {5.0, 5.0};
        double[] repaired = {1.0, 1.0};
        double[] decodedRepaired = {1.1, 1.1};
        double objectiveVal = 5.0;
        double penaltyVal = 2.0;

        CMAESOptimizer.FitnessFunction spyFunction = spy(fitnessFunction);
        doReturn(repaired).when(spyFunction).repair(point);
        doReturn(decodedRepaired).when(spyFunction).decode(repaired);
        doReturn(penaltyVal).when(spyFunction).penalty(point, repaired);
        when(optimizer.computeObjectiveValue(decodedRepaired)).thenReturn(objectiveVal);

        double result = spyFunction.value(point);

        assertEquals(objectiveVal + penaltyVal, result, 1e-9);
    }

    @Test
    public void testValue_Maximize_WithRepair() throws Exception {
        CMAESOptimizer optimizer = mock(CMAESOptimizer.class);
        CMAESOptimizer.FitnessFunction fitnessFunction = new CMAESOptimizer.FitnessFunction();
        setOuterInstance(fitnessFunction, optimizer);

        setField(fitnessFunction, "isRepairMode", true);
        setField(fitnessFunction, "boundaries", new double[]{0.0, 1.0});
        setField(fitnessFunction, "isMinimize", false);

        double[] point = {5.0, 5.0};
        double[] repaired = {1.0, 1.0};
        double[] decodedRepaired = {1.1, 1.1};
        double objectiveVal = 5.0;
        double penaltyVal = 2.0;

        CMAESOptimizer.FitnessFunction spyFunction = spy(fitnessFunction);
        doReturn(repaired).when(spyFunction).repair(point);
        doReturn(decodedRepaired).when(spyFunction).decode(repaired);
        doReturn(penaltyVal).when(spyFunction).penalty(point, repaired);
        when(optimizer.computeObjectiveValue(decodedRepaired)).thenReturn(objectiveVal);

        double result = spyFunction.value(point);

        assertEquals(-(objectiveVal + penaltyVal), result, 1e-9);
    }

    private void setField(Object target, String fieldName, Object value) throws Exception {
        java.lang.reflect.Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }
}
